cat >> src/pricing.js <<'EOF'

/** Points multiplier by membership tier. Anyone else earns the base rate. */
const MEMBER_MULTIPLIER = { silver: 2, gold: 3 };

const EXPRESS_BONUS = 50;

/**
 * Loyalty points for an order: one per whole dollar of the net amount (in cents),
 * times the member multiplier, plus a bonus for express shipping. Using a discount
 * code halves the total, bonus included, unless the member is gold. Whole points,
 * rounded down.
 */
export function loyaltyPoints(netCents, { member, express = false, discounted = false } = {}) {
  const earned = Math.floor(cents(netCents) / 100) * (MEMBER_MULTIPLIER[member] ?? 1);
  const total = earned + (express ? EXPRESS_BONUS : 0);
  return member !== "gold" && discounted ? Math.floor(total / 2) : total;
}
EOF
sed -i 's|import { add, percentOf } from "./money.js";|import { add, cents, percentOf } from "./money.js";|' src/pricing.js
sed -i 's|import { discountFor, priceCart, subtotal }|import { discountFor, loyaltyPoints, priceCart, subtotal }|' test/pricing.test.js
cat >> test/pricing.test.js <<'EOF'

test("loyalty points are one per whole dollar of the net amount", () => {
  assert.equal(loyaltyPoints(2399), 23);
  assert.equal(loyaltyPoints(99), 0);
});

test("silver members earn double and gold members triple", () => {
  assert.equal(loyaltyPoints(2300, { member: "silver" }), 46);
  assert.equal(loyaltyPoints(2300, { member: "gold" }), 69);
});

test("express shipping adds a 50 point bonus", () => {
  assert.equal(loyaltyPoints(2300, { express: true }), 73);
});

test("a discount code halves the points, rounding down, but not for gold", () => {
  assert.equal(loyaltyPoints(2300, { discounted: true }), 11);
  assert.equal(loyaltyPoints(2300, { member: "silver", discounted: true }), 23);
  assert.equal(loyaltyPoints(2300, { member: "gold", discounted: true }), 69);
});

test("the halving applies to the express bonus too", () => {
  assert.equal(loyaltyPoints(2300, { express: true, discounted: true }), 36);
  assert.equal(loyaltyPoints(2300, { member: "gold", express: true, discounted: true }), 119);
});
EOF
npm test 2>&1 | tail -12

